static void check(bool b,const char*s){if(!b)throw std::runtime_error(s);}
int main(int argc,char**argv){try{check(argc==3,"resource + isolated user required");check(int(private_input::known_phrase::classify(std::string(argv[1])+"/essay.txt","另朵"))==2,"synthetic phrase must be eligible_new");check(pi_initialize(argv[1],argv[2],0)!=0,"initialize");auto s=pi_create_session();check(s&&pi_set_private(s,1),"production-style private Rime session");using Scope=private_input::PhraseFieldScope;const void*enginePaths=nullptr;check(private_input::phraseNoticeAllowed(enginePaths,Scope::normal,false,false,true),"production nil paths + stateless Rime permits normal authorized notice");for(auto field:{Scope::password,Scope::privateField,Scope::unknown})check(!private_input::phraseNoticeAllowed(enginePaths,field,false,false,true),"nonnormal fields suppress notice");check(!private_input::phraseNoticeAllowed(enginePaths,Scope::normal,true,false,true),"disabled suppresses");check(!private_input::phraseNoticeAllowed(enginePaths,Scope::normal,false,true,true),"secure suppresses");check(!private_input::phraseNoticeAllowed(enginePaths,Scope::normal,false,false,false),"local learning disabled suppresses");int fixture=0;check(!private_input::phraseNoticeAllowed(&fixture,Scope::normal,false,false,true),"fixture paths do not announce production learning");for(char c:std::string("lingduo"))pi_process_key(s,c,0);std::string combined;unsigned selections=0;for(const auto&word:{std::string("另"),std::string("朵")}){auto n=pi_load_candidate_batch(s,0,128);size_t absolute=SIZE_MAX;for(size_t i=0;i<n;++i)if(word==pi_batch_candidate_text(s,i)){absolute=pi_batch_candidate_index(s,i);break;}check(absolute!=SIZE_MAX,"named synthetic candidate");check(std::string(pi_selected_prefix(s))==combined,"selected prefix matches tracked segments");check(pi_select_candidate_absolute(s,absolute)!=0,"select");combined+=word;++selections;std::string commit=pi_take_commit(s);check(selections==1?commit.empty():commit==combined,"partial empty then final exact commit");(void)pi_preedit(s);}
 check(combined=="另朵"&&pi_auto_phrase_status(combined.c_str())==2,"complete eligible synthetic commit");pi_destroy_session(s);pi_finalize();std::cout<<"PASS eligible_new=2, privateRime=true, segments=2, prefixMatch=true, finalCommitMatch=true, productionNilNormalAllowed=true, passwordPrivateUnknownDisabledSecureUnauthorizedBlocked=true\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
